public long updateRto(long sampleMs) {
    // Проверка на корректность входных данных: RTT (Round-Trip Time) не может быть отрицательным
    if (sampleMs < 0) {
        throw new IllegalArgumentException("negative RTT sample");
    }

    // Если это первое измерение RTT (srtt еще не инициализировано, значение < 0)
    if (srtt < 0) {
        // Инициализируем сглаженное значение RTT (SRTT) первым образцом
        srtt = sampleMs;
        // Инициализируем дисперсию RTT (RTTVAR) как половину первого образца
        rttvar = sampleMs / 2;
    } else {
        // Вычисляем абсолютную разницу между текущим сглаженным RTT и новым образцом
        long delta = Math.abs(srtt - sampleMs);

        // Обновляем дисперсию RTT (RTTVAR) по формуле экспоненциального сглаживания:
        // RTTVAR = (3 * RTTVAR + |SRTT - RTT|) / 4
        // Это обеспечивает плавное изменение оценки дисперсии
        rttvar = (3 * rttvar + delta) / 4;

        // Обновляем сглаженное значение RTT (SRTT) по формуле экспоненциального сглаживания:
        // SRTT = (7 * SRTT + RTT) / 8
        // Это обеспечивает плавное изменение оценки среднего RTT
        srtt = (7 * srtt + sampleMs) / 8;
    }

    // Вычисляем таймаут повторной передачи (RTO) по формуле:
    // RTO = SRTT + max(гранулярность таймера, 4 * RTTVAR)
    // Гранулярность учитывает минимальный шаг таймера системы,
    // а 4 * RTTVAR обеспечивает запас на вариативность задержки
    long rto = srtt + Math.max(granularityMs, 4 * rttvar);

    // Ограничиваем значение RTO в допустимых пределах:
    // Минимум 1000 мс (1 секунда) — чтобы избежать слишком частых повторных передач
    // Максимум 60000 мс (60 секунд) — чтобы избежать слишком долгих ожиданий
    return Math.min(Math.max(rto, 1000L), 60000L);
}
