// WriteFileAtomic атомарно записывает данные в файл по указанному пути.
// Это гарантирует, что файл либо полностью записан, либо остаётся в исходном состоянии,
// избегая частичных записей при сбоях.
func WriteFileAtomic(path string, data []byte, perm os.FileMode) error {
	// Создаём временный файл в той же директории, что и целевой файл.
	// Это важно, так как os.Rename работает атомарно только в пределах одной файловой системы.
	tmp, err := os.CreateTemp(filepath.Dir(path), ".tmp-*")
	if err != nil {
		return err
	}
	// Гарантируем удаление временного файла при выходе из функции,
	// если что-то пойдёт не так (например, ошибка записи или синхронизации).
	defer os.Remove(tmp.Name())

	// Записываем данные во временный файл.
	if _, err = tmp.Write(data); err == nil {
		// Синхронизируем данные с диском, чтобы убедиться, что они физически записаны.
		err = tmp.Sync()
	}

	// Закрываем временный файл.
	// Если предыдущие операции прошли успешно, сохраняем ошибку от Close, если она есть.
	if cerr := tmp.Close(); err == nil {
		err = cerr
	}

	// Если ошибок не было, устанавливаем нужные права доступа для временного файла.
	if err == nil {
		err = os.Chmod(tmp.Name(), perm)
	}

	// Если на каком-то этапе возникла ошибка, возвращаем её.
	if err != nil {
		return err
	}

	// Атомарно переименовываем временный файл в целевой путь.
	// Это завершающий шаг, который делает запись видимой для других процессов.
	return os.Rename(tmp.Name(), path)
}
