  // Если версия не 2, выбрасываем ошибку, так как другие версии не поддерживаются.
  if (b0 >> 6 !== 2) throw new Error(`unsupported RTP version ${b0 >> 6}`);

  // Извлекаем количество идентификаторов источников (CSRC) из последних 4 битов первого байта.
  // Каждый CSRC занимает 4 байта в заголовке.
  const csrcCount = b0 & 0x0f;

  // Базовый заголовок занимает 12 байт. Добавляем размер блока CSRC (4 байта на каждый CSRC).
  let offset = 12 + csrcCount * 4;

  // Проверяем наличие расширения заголовка (бит X в первом байте, маска 0x10).
  if (b0 & 0x10) {
