    // Минимальный размер расширения: 2 байта (ID) + 2 байта (длина) = 4 байта.
    // Проверяем, что в буфере достаточно данных для чтения заголовка расширения.
    if (buf.length < offset + 4) throw new RangeError("truncated header extension");

    // Читаем длину расширения (в 32-битных словах) из байтов offset+2 и offset+3.
    // Умножаем на 4, чтобы получить длину в байтах.
    // Добавляем 4 байта (сам заголовок расширения) + длина данных расширения.
    offset += 4 + view.getUint16(offset + 2) * 4;
