pub fn parse_nmea(line: &str) -> Result<Vec<&str>, NmeaError> {
    // Удаляем пробельные символы и переводы строк с конца входной строки,
    // чтобы они не мешали дальнейшему парсингу.
    let line = line.trim_end();

    // Проверяем, что строка начинается с символа '$', который является
    // обязательным префиксом для всех предложений NMEA.
    // Если префикс отсутствует, возвращаем ошибку NoStart.
    let body = line.strip_prefix('$').ok_or(NmeaError::NoStart)?;

    // Разделяем тело предложения на полезную нагрузку (payload) и контрольную сумму (checksum).
    // Контрольная сумма всегда находится после последнего символа '*' в предложении.
    // Если символ '*' не найден, возвращаем ошибку NoChecksum.
    let (payload, checksum) = body.rsplit_once('*').ok_or(NmeaError::NoChecksum)?;

    // Преобразуем строку контрольной суммы из шестнадцатеричного представления в число u8.
    // Если преобразование не удалось (например, из-за невалидных символов), возвращаем ошибку BadChecksum.
    let expected = u8::from_str_radix(checksum, 16).map_err(|_| NmeaError::BadChecksum)?;

    // Вычисляем фактическую контрольную сумму XOR для всех байтов полезной нагрузки.
    // Алгоритм XOR-контрольной суммы является стандартным для протокола NMEA.
    let actual = payload.bytes().fold(0u8, |acc, b| acc ^ b);

    // Сравниваем вычисленную контрольную сумму с ожидаемой.
    // Если они не совпадают, возвращаем ошибку Mismatch с указанием ожидаемого и фактического значений.
    if actual != expected {
        return Err(NmeaError::Mismatch { expected, actual });
    }

    // Если все проверки пройдены, разбиваем полезную нагрузку на поля по запятой
    // и возвращаем вектор ссылок на эти поля.
    Ok(payload.split(',').collect())
}
