void receivesWholeDatagram() throws Exception {
    // Создаем полезную нагрузку размером 2000 байт
    byte[] payload = new byte[2000];

    // Отправляем датаграмму размером 2000 байт
    sender.send(new DatagramPacket(payload, payload.length, receiverAddress));

    // ИСПРАВЛЕНИЕ: Буфер приема должен быть не меньше размера отправляемой датаграммы.
    // Было: new byte[1500] — недостаточно для 2000 байт.
    // Стало: new byte[2000] — достаточно для всей датаграммы.
    DatagramPacket packet = new DatagramPacket(new byte[2000], 2000);

    // Получаем датаграмму. Теперь весь пакет (2000 байт) поместится в буфер.
    receiver.receive(packet);
